<script setup lang="ts">
const api=useApi(); const { data: jobs, refresh }=await useAsyncData('admin-jobs',()=>api.request<any[]>('/admin/jobs').catch(()=>[]))
async function setStatus(id:string,status:string){await api.request(`/admin/jobs/${id}/status`,{method:'POST',body:{status}});await refresh()}
</script>
<template><div><div class="mb-5"><p class="label-mono text-signal-deep">B2C operations</p><h1 class="mt-1 font-display text-[32px] tracking-[-.04em]">Home jobs & escrow.</h1><p class="mt-1 text-[11.5px] text-ink/45">Camera reviews, contractor bids and LineAssure milestones.</p></div><div class="grid gap-3"><div v-for="j in jobs" :key="j._id" class="a-card grid gap-4 p-4 md:grid-cols-[1fr_auto] md:items-center"><div><div class="flex items-center gap-2"><p class="font-mono text-[8px] text-ink/35">{{ j.ref }}</p><StatusPill :status="j.status"/><span class="font-mono text-[8px] uppercase text-ink/30">{{ j.healthScore ? `${j.healthScore}/100` : 'not analyzed' }}</span></div><p class="mt-1 font-display text-[19px]">{{ j.address }} · {{ j.city }}</p><p class="mt-0.5 line-clamp-1 text-[11px] text-ink/45">{{ j.issue }}</p></div><div class="flex items-center gap-2"><select :value="j.status" class="rounded border border-ink/12 bg-bone px-2 py-1.5 font-mono text-[8px] uppercase" @change="setStatus(j._id, ($event.target as HTMLSelectElement).value)"><option>new</option><option>analyzing</option><option>report_ready</option><option>bidding</option><option>awarded</option><option>in_progress</option><option>complete</option><option>cancelled</option></select><span class="font-mono text-[9px] text-ink/35">{{ j.defects?.length || 0 }} findings</span></div></div></div></div></template>
